import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cpp_src = r"""
#include <torch/extension.h>
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""
cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_fp16.h>
#include <mma.h>
#include <cuda_pipeline.h>
#include <math.h>
using namespace nvcuda;
__device__ __forceinline__ float warpReduceSum(float v) {
    for (int offset = 16; offset > 0; offset >>= 1)
        v += __shfl_xor_sync(0xffffffffu, v, offset);
    return v;
}
__device__ __forceinline__ float warpReduceMax(float v) {
    for (int offset = 16; offset > 0; offset >>= 1)
        v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, offset));
    return v;
}
// Tensor-core (WMMA) flash-style SDPA. One CTA computes a 64-row query tile for
// one (batch*head): scores = Q_tile @ K^T via mma (K-dim tiled, fp32 accum),
// warp-cooperative row softmax, then O_tile = P @ V via mma (fp32 accum).
template <int NT>  // S = 64 * NT
__global__ void __launch_bounds__(512) sdpa_kernel(const __half* __restrict__ Q,
                            const __half* __restrict__ K,
                            const __half* __restrict__ V,
                            __half* __restrict__ O,
                            int S, int D, float scale) {
    constexpr int MROWS = 64;
    constexpr int QK_STRIDE = 40;
    constexpr int V_STRIDE = 72;
    constexpr int O_STRIDE = 68;
    extern __shared__ char smem_raw[];
    const int SS = S + 4;
    const int PS = S + 8;
    const size_t scores_bytes = (size_t)MROWS * SS * sizeof(float);
    float*  scores = reinterpret_cast<float*>(smem_raw);
    // Phase-1 budget: k_s1 aliases the scores region, which is only written
    // after the K-dim accumulation loop (when the k_s1 stage is dead).
    __half* k_s1 = reinterpret_cast<__half*>(smem_raw);
    __half* k_s0 = reinterpret_cast<__half*>(smem_raw + scores_bytes);
    __half* q_s0 = k_s0 + (size_t)S * QK_STRIDE;
    __half* q_s1 = q_s0 + (size_t)MROWS * QK_STRIDE;
    // Phase-2 budget: v_s0 aliases scores/p_s (both dead before the first
    // v_s0 fill inside the nc loop); p_s itself is declared after softmax.
    __half* v_s0 = reinterpret_cast<__half*>(smem_raw);
    __half* v_s1 = v_s0 + (size_t)S * V_STRIDE;
    float*  o_s = reinterpret_cast<float*>(v_s1 + (size_t)S * V_STRIDE);
    const int bh = blockIdx.y;
    const int q0 = blockIdx.x * MROWS;
    const long base = (long)bh * (long)S * (long)D;
    const __half* Qg = Q + base;
    const __half* Kg = K + base;
    const __half* Vg = V + base;
    __half* Og = O + base;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int warp_m = warp & 3;
    const int warp_n = warp >> 2;
    // Phase 1: scores = Q_tile @ K^T (tensor cores, fp32 accumulation),
    // with 2-stage cp.async pipelining of the Q/K tiles.
    auto load_qk = [&](int kc, __half* qb, __half* kb) {
        for (int idx = tid; idx < MROWS * 4; idx += 512) {
            const int r = idx >> 2;
            const int c8 = (idx & 3) << 3;
            __pipeline_memcpy_async(qb + r * QK_STRIDE + c8,
                                    Qg + (long)(q0 + r) * D + kc + c8, 16);
        }
        for (int idx = tid; idx < S * 4; idx += 512) {
            const int r = idx >> 2;
            const int c8 = (idx & 3) << 3;
            __pipeline_memcpy_async(kb + r * QK_STRIDE + c8,
                                    Kg + (long)r * D + kc + c8, 16);
        }
        __pipeline_commit();
    };
    auto load_v = [&](int nc, __half* vb) {
        for (int idx = tid; idx < S * 8; idx += 512) {
            const int r = idx >> 3;
            const int c8 = (idx & 7) << 3;
            __pipeline_memcpy_async(vb + r * V_STRIDE + c8,
                                    Vg + (long)r * D + nc + c8, 16);
        }
        __pipeline_commit();
    };
    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[NT];
    #pragma unroll
    for (int t = 0; t < NT; ++t) wmma::fill_fragment(acc[t], 0.0f);
    load_qk(0, q_s0, k_s0);
    int buf = 0;
    for (int kc = 0; kc < D; kc += 32) {
        const int nkc = kc + 32;
        __half* qb = buf ? q_s1 : q_s0;
        __half* kb = buf ? k_s1 : k_s0;
        if (nkc < D) load_qk(nkc, buf ? q_s0 : q_s1, buf ? k_s0 : k_s1);
        __pipeline_wait_prior(nkc < D ? 1 : 0);
        __syncthreads();
        #pragma unroll
        for (int ks = 0; ks < 2; ++ks) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> a;
            wmma::load_matrix_sync(a, qb + (warp_m * 16) * QK_STRIDE + ks * 16, QK_STRIDE);
            #pragma unroll
            for (int t = 0; t < NT; ++t) {
                wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::col_major> b;
                wmma::load_matrix_sync(b, kb + (warp_n * (NT * 16) + t * 16) * QK_STRIDE + ks * 16, QK_STRIDE);
                wmma::mma_sync(acc[t], a, b, acc[t]);
            }
        }
        __syncthreads();
        buf ^= 1;
    }
    #pragma unroll
    for (int t = 0; t < NT; ++t)
        wmma::store_matrix_sync(scores + (warp_m * 16) * SS + warp_n * (NT * 16) + t * 16,
                                acc[t], SS, wmma::mem_row_major);
    __syncthreads();
    // Safe row softmax: 16 warps x 4 rows. Normalized values are carried in
    // registers until every warp has finished reading scores, then stored as
    // fp16 over the (now dead) scores region, which p_s aliases to save smem.
    float pvals[MROWS / 16][2 * NT];
    float pinv[MROWS / 16];
    #pragma unroll
    for (int i = 0; i < MROWS / 16; ++i) {
        const int r = warp * (MROWS / 16) + i;
        const float* srow = scores + r * SS;
        float mx = -1e30f;
        #pragma unroll
        for (int vi = 0; vi < 2 * NT; ++vi) {
            pvals[i][vi] = srow[lane + vi * 32] * scale;
            mx = fmaxf(mx, pvals[i][vi]);
        }
        mx = warpReduceMax(mx);
        float s = 0.0f;
        #pragma unroll
        for (int vi = 0; vi < 2 * NT; ++vi) {
            pvals[i][vi] = __expf(pvals[i][vi] - mx);
            s += pvals[i][vi];
        }
        s = warpReduceSum(s);
        pinv[i] = 1.0f / s;
    }
    __syncthreads();  // scores fully consumed; its storage may now be reused
    __half* p_s = reinterpret_cast<__half*>(smem_raw);  // alias dead scores
    #pragma unroll
    for (int i = 0; i < MROWS / 16; ++i) {
        const int r = warp * (MROWS / 16) + i;
        __half* prow = p_s + r * PS;
        #pragma unroll
        for (int vi = 0; vi < 2 * NT; ++vi)
            prow[lane + vi * 32] = __float2half(pvals[i][vi] * pinv[i]);
    }
    __syncthreads();
    // Prefetch the first V tile into v_s1 (in its own full-sized slot). This
    // must happen after the softmax barrier: v_s1 overlaps the old scores
    // region, so issuing it earlier would race with the score reads above.
    load_v(0, v_s1);
    // Phase 2: O_tile = P @ V (tensor cores, fp32 accumulation), D tiled by 64,
    // with 2-stage cp.async pipelining of the V tiles. Keep the stationary P
    // operand fragments in registers across all D tiles to avoid reloading the
    // same 16x16 WMMA A fragments from shared memory for every output tile.
    constexpr int KFRAGS = 4 * NT;
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> pfrag[KFRAGS];
    #pragma unroll
    for (int kf = 0; kf < KFRAGS; ++kf)
        wmma::load_matrix_sync(pfrag[kf], p_s + (warp_m * 16) * PS + kf * 16, PS);
    __syncthreads();  // all warps done reading p_s before cp.async overwrites it (v_s0 aliases p_s)
    int vbuf = 1;
    for (int nc = 0; nc < D; nc += 64) {
        const int nnc = nc + 64;
        __half* vb = vbuf ? v_s1 : v_s0;
        if (nnc < D) load_v(nnc, vbuf ? v_s0 : v_s1);
        __pipeline_wait_prior(nnc < D ? 1 : 0);
        __syncthreads();
        // Split the K-dim (S) reduction into two independent fp32 accumulator
        // fragments (even/odd k fragments) to break the single dependent HMMA
        // chain and expose warp-level ILP to the tensor cores.
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> oacc0, oacc1;
        wmma::fill_fragment(oacc0, 0.0f);
        wmma::fill_fragment(oacc1, 0.0f);
        #pragma unroll
        for (int kf = 0; kf < KFRAGS; kf += 2) {
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> b0;
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> b1;
            wmma::load_matrix_sync(b0, vb + (kf * 16) * V_STRIDE + warp_n * 16, V_STRIDE);
            wmma::load_matrix_sync(b1, vb + ((kf + 1) * 16) * V_STRIDE + warp_n * 16, V_STRIDE);
            wmma::mma_sync(oacc0, pfrag[kf], b0, oacc0);
            wmma::mma_sync(oacc1, pfrag[kf + 1], b1, oacc1);
        }
        #pragma unroll
        for (int e = 0; e < 8; ++e) oacc0.x[e] += oacc1.x[e];
        wmma::store_matrix_sync(o_s + (warp_m * 16) * O_STRIDE + warp_n * 16,
                                oacc0, O_STRIDE, wmma::mem_row_major);
        __syncthreads();
        for (int idx = tid; idx < MROWS * 32; idx += 512) {
            const int r = idx >> 5;
            const int c2 = (idx & 31) << 1;
            __half2 hv;
            hv.x = __float2half(o_s[r * O_STRIDE + c2]);
            hv.y = __float2half(o_s[r * O_STRIDE + c2 + 1]);
            unsigned int packed = *reinterpret_cast<const unsigned int*>(&hv);
            __stcs(reinterpret_cast<unsigned int*>(Og + (long)(q0 + r) * D + nc + c2), packed);
        }
        __syncthreads();
        vbuf ^= 1;
    }
}
template <int NT>
static void sdpa_launch(const __half* q, const __half* k, const __half* v, __half* o,
                        int S, int D, float scale, dim3 grid, size_t smem, cudaStream_t stream) {
    static bool configured = false;
    if (!configured) {
        int dev = 0;
        cudaGetDevice(&dev);
        int max_optin = 0;
        cudaDeviceGetAttribute(&max_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
        TORCH_CHECK((size_t)max_optin >= smem, "kernel needs ", smem, "B dynamic smem but device allows ", max_optin);
        cudaError_t attr_err = cudaFuncSetAttribute(sdpa_kernel<NT>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
        TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));
        configured = true;
    }
    sdpa_kernel<NT><<<grid, 512, smem, stream>>>(q, k, v, o, S, D, scale);
}
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q/K/V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf, "expected float16 inputs");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "inputs must be contiguous");
    auto aligned_to = [](const void* p, size_t a) { return reinterpret_cast<size_t>(p) % a == 0; };
    TORCH_CHECK(aligned_to(Q.data_ptr(), 16) && aligned_to(K.data_ptr(), 16) && aligned_to(V.data_ptr(), 16), "Q/K/V must be 16-byte aligned for cp.async");
    const int B = Q.size(0);
    const int H = Q.size(1);
    const int S = Q.size(2);
    const int D = Q.size(3);
    TORCH_CHECK(S % 64 == 0 && S <= 256, "S must be a multiple of 64 up to 256");
    TORCH_CHECK(D % 128 == 0, "D must be a multiple of 128");
    auto O = torch::empty_like(Q);
    dim3 grid(S / 64, B * H);
    const size_t scores_b = (size_t)64 * (S + 4) * sizeof(float);
    // Phase 1: k_s1 aliases the scores region, so only one K stage is extra.
    const size_t smem_p1 = scores_b + (size_t)S * 40 * sizeof(__half) + (size_t)2 * 64 * 40 * sizeof(__half);
    // Phase 2: p_s and v_s0 alias the scores region, so only the two V stages and o_s count.
    const size_t smem_p2 = (size_t)2 * S * 72 * sizeof(__half) + (size_t)64 * 68 * sizeof(float);
    const size_t smem = std::max(smem_p1, smem_p2);
    const float scale = 1.0f / sqrtf((float)D);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    const __half* q = reinterpret_cast<const __half*>(Q.data_ptr<at::Half>());
    const __half* k = reinterpret_cast<const __half*>(K.data_ptr<at::Half>());
    const __half* v = reinterpret_cast<const __half*>(V.data_ptr<at::Half>());
    __half* o = reinterpret_cast<__half*>(O.data_ptr<at::Half>());
    switch (S / 64) {
        case 1: sdpa_launch<1>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 2: sdpa_launch<2>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 3: sdpa_launch<3>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        case 4: sdpa_launch<4>(q, k, v, o, S, D, scale, grid, smem, stream); break;
        default: TORCH_CHECK(false, "unsupported sequence length");
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return O;
}
"""
_sdpa = load_inline(
    name="sdpa_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["sdpa_forward"],
    with_cuda=True,
    extra_cuda_cflags=["-O3"],
    verbose=False,
)
class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return _sdpa.sdpa_forward(Q, K, V)
batch_size = 2
num_heads = 32
sequence_length = 256
embedding_dimension = 1024
def get_inputs():
    Q = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    K = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    V = torch.randn(batch_size, num_heads, sequence_length, embedding_dimension, device='cuda', dtype=torch.float16)
    return [Q, K, V]
def get_init_inputs():
    return []

