        for (int ks = 0; ks < 2; ++ks) {
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> a;
            wmma::load_matrix_sync(a, qb + (warp_m * 16) * QK_STRIDE + ks * 16, QK_STRIDE);
