    // with 2-stage cp.async pipelining of the Q/K tiles.
    auto load_qk = [&](int kc, __half* qb, __half* kb) {
        for (int idx = tid; idx < MROWS * 4; idx += 512) {
            const int r = idx >> 2;
            const int c8 = (idx & 3) << 3;
            __pipeline_memcpy_async(qb + r * QK_STRIDE + c8,
