            const int r = idx >> 2;
            const int c8 = (idx & 3) << 3;
            __pipeline_memcpy_async(kb + r * QK_STRIDE + c8,
                                    Kg + (long)r * D + kc + c8, 16);
        }
        __pipeline_commit();
    };
    auto load_v = [&](int nc, __half* vb) {
        for (int idx = tid; idx < S * 8; idx += 512) {
            const int r = idx >> 3;
            const int c8 = (idx & 7) << 3;
            __pipeline_memcpy_async(vb + r * V_STRIDE + c8,
                                    Vg + (long)r * D + nc + c8, 16);
