    __syncthreads();
    // Phase 2: O_tile = P @ V (tensor cores, fp32 accumulation), D tiled by 64,
    // with 2-stage cp.async pipelining of the V tiles. Keep the stationary P
    // operand fragments in registers across all D tiles to avoid reloading the
    // same 16x16 WMMA A fragments from shared memory for every output tile.
    constexpr int KFRAGS = 4 * NT;
