        // fragments (even/odd k fragments) to break the single dependent HMMA
        // chain and expose warp-level ILP to the tensor cores.
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> oacc0, oacc1;
        wmma::fill_fragment(oacc0, 0.0f);
        wmma::fill_fragment(oacc1, 0.0f);
