        for (int kf = 0; kf < KFRAGS; kf += 2) {
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> b0;
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> b1;
